  FROM creatures WHERE slug IN ('aardan-tek', 'grackle-tooth', 'greot-hunter', 'mastadonoid', 'noli-bushman', 'yeno', 'armored-slayer', 'black-bear', 'brown-bear', 'grizzly-bear', 'kodiak-bear', 'polar-bear', 'mutant-mega-damage-bear', 'red-and-gray-fox', 'common-gray-wolf', 'northern-timber-wolf', 'sled-dog', 'cadborosaurus', 'faerie-bot', 'fury-beetle', 'loup-garou', 'ogopogo-dragon-adult', 'ogopogo-dragon-hatchling', 'spirit-sasquatch', 'true-sasquatch', 'typical-dinosaur-small', 'typical-dinosaur-medium', 'typical-dinosaur-large', 'demon-bear', 'dsonoqua-the-cannibal-woman', 'sedna-the-sea-hag', 'windigo-demon', 'wishpoosh-the-demon-beaver', 'tornaq-the-spirit-bear');
SELECT 'and 11 of them are playable' AS assertion, count(*) AS got, 11 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('aardan-tek', 'grackle-tooth', 'greot-hunter', 'mastadonoid', 'noli-bushman', 'yeno', 'armored-slayer', 'black-bear', 'brown-bear', 'grizzly-bear', 'kodiak-bear', 'polar-bear', 'mutant-mega-damage-bear', 'red-and-gray-fox', 'common-gray-wolf', 'northern-timber-wolf', 'sled-dog', 'cadborosaurus', 'faerie-bot', 'fury-beetle', 'loup-garou', 'ogopogo-dragon-adult', 'ogopogo-dragon-hatchling', 'spirit-sasquatch', 'true-sasquatch', 'typical-dinosaur-small', 'typical-dinosaur-medium', 'typical-dinosaur-large', 'demon-bear', 'dsonoqua-the-cannibal-woman', 'sedna-the-sea-hag', 'windigo-demon', 'wishpoosh-the-demon-beaver', 'tornaq-the-spirit-bear');
SELECT 'the creatures carry 100 attacks' AS assertion, count(*) AS got, 100 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('aardan-tek', 'grackle-tooth', 'greot-hunter', 'mastadonoid', 'noli-bushman', 'yeno', 'armored-slayer', 'black-bear', 'brown-bear', 'grizzly-bear', 'kodiak-bear', 'polar-bear', 'mutant-mega-damage-bear', 'red-and-gray-fox', 'common-gray-wolf', 'northern-timber-wolf', 'sled-dog', 'cadborosaurus', 'faerie-bot', 'fury-beetle', 'loup-garou', 'ogopogo-dragon-adult', 'ogopogo-dragon-hatchling', 'spirit-sasquatch', 'true-sasquatch', 'typical-dinosaur-small', 'typical-dinosaur-medium', 'typical-dinosaur-large', 'demon-bear', 'dsonoqua-the-cannibal-woman', 'sedna-the-sea-hag', 'windigo-demon', 'wishpoosh-the-demon-beaver', 'tornaq-the-spirit-bear');

