INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('aardan-tek', 'Aardan Tek', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"2D6+8","ME":"2D6+8","MA":"2D6+4","PS":"3D6","PP":"2D6+8","PE":"3D6","PB":"1D6","Spd":"4D6"}', '5D6+PE', '6D6', NULL, '5D6', NULL, 'Hit Points are 5D6 plus the P.E. number, plus 1D6 per level of experience from level one (the book prints that per-level gain as ''1D6 M.D.'' on the Hit Points line). P.P.E. is 5D6 or as the magic O.C.C. gives. An S.D.C. being: needs magic or M.D.C. armor against M.D. weapons. I.S.P. is not printed (Minor Psychic).', NULL, NULL, '{"initiative":3,"parry":2,"dodge":2,"roll":1}', '+2 to save vs Horror Factor. All R.C.C. bonuses are in addition to attribute bonuses. Attacks per melee are those of the Hand to Hand skill, never fewer than two. Takes only half the usual strike, parry and dodge penalties when blinded or in total darkness, provided there is a scent to work from. Vulnerability: -10% on all swimming skills.', 'Scent skills: recognize common and strong scents 70% +3% per level, out to 100 feet (30.5 m) a level; identify specific odors 58% +2% per level, out to 25 feet (7.6 m) a level; track by smell alone 34% +4% per level.', 'Keen eyes with a 200 degree field of view. Leaps six feet (1.8 m) up and eight feet (2.4 m) across, half again as far with a run-up. The short trunk is prehensile, swivels any way, and smells as well as a dog: it picks out familiar odors, gases, food, animals and the route a group took, and with a reference sample or prior familiarity it singles out one person, or a drug or poison in food. Tracking by nose is rolled every 1000 feet (305 m), or every 500 on a faint trail or one under light rain or snow; a miss loses the trail for the moment, two hits in three tries recover it, two misses lose it for good, and no trail older than 24 hours can be followed.', 'By O.C.C.; 55% are magic users of some kind', 'Every one is a Minor Psychic with the usual abilities; Mystics alone have more', '6-7 feet (1.8 to 2.1 m) tall', '160 to 230 pounds (72 to 103.5 kg)', '80-100 years', 'Anywhere in North America, thickest in Ontario, Michigan and the Ohio Valley; small parties study magical and dimensional sites such as the Calgary Rift and the Wyoming Medicine Wheel, and they keep clear of Atlantis', 'None formally; drawn to artists, musicians, philosophers, scholars, scientists, other mages, dragons and Faerie Folk. Some have settled as students in the Federation of Magic, Lazlo and New Lazlo', 'The CS, human supremacists and anyone against magic or D-Bees; they count demons and other supernatural beings as dangerous and evil', 'Optional player character. Any Practitioner of Magic O.C.C., though Witchcraft and Necromancy are usually shunned and Temporal Magic and Techno-Wizardry are favorites; Mystics and Ley Line Walkers are 20% each and other kinds of mage 15%. Most Adventurer and Scholar O.C.C.s also fit, Operator, Scholar and Scientist above all. No Juicers, Crazies or full conversion cyborgs. Starts with custom armor, light (30 M.D.C.) or medium (50 M.D.C.), two modern weapons with four spare E-clips each and basic gear, but no magic items.', 'The Long Nose Aliens: scholarly D-Bees with a stubby trunk above the mouth, from a world where magic and technology live side by side. They came to Rifts Earth on purpose, as a first venture into dimensional travel, to study it.', 'Rifts World Book 20: Canada p.130-132'),
('grackle-tooth', 'Grackle Tooth', 'humanoid', 'rifts', 1, 'Any, but lean toward good, Anarchist or Aberrant', '{"IQ":"1D6+8","ME":"1D6+9","MA":"2D6+14","PS":"2D6+22","PP":"2D6+10","PE":"2D6+10","PB":"1D6+6","Spd":"2D6+10"}', NULL, NULL, '2D4x10+PE', '3D6', NULL, 'M.D.C. is 2D4x10 plus the P.E. number, plus 3D6 per level of experience from level one. Supernatural physical attributes (Supernatural P.S.). On an S.D.C. world: Hit Points 1D6x10 plus P.E., S.D.C. 1D6x10, +1D6 H.P. per level, natural A.R. 9. Heals 2D6 M.D.C. per 12 hours. No I.S.P.', NULL, NULL, '{"initiative":2,"strike":1,"parry":2,"pull_punch":3,"roll":2}', '+5 to save vs Horror Factor, +2 vs poison and toxins, +6 vs disease, +1 vs psionic attack, mind-control drugs and magical illusions. The parry bonus covers the tail. All in addition to attribute bonuses. Attacks per melee are those of the Hand to Hand skill plus one for the tail, never fewer than three. -3 to strike when the tail fires a handgun, aimed shots included.', 'Mechanical aptitude: one extra Modern W.P., plus Basic Electronics and Basic Mechanics at +10% each; every mechanical, repair or building skill taken through the O.C.C. gets a further +5%.', 'Keen eyesight, great strength and quick reflexes. Immune to carcinogens and to heat, but dislikes cold. A prehensile tail 12-15 feet (3.6 to 4.6 m) long gives one more attack each round and can swing melee weapons or even shoot a handgun; if cut or lost it grows back a foot (0.3 m) a month.', 'None', 'None', '8-10 feet (2.4 to 3 m) tall', '600 to 800 pounds (270 to 360 kg)', '200-300 years', 'Likes warm, dry country. Rare: under 4,000 on Earth, half in Lone Star and most others in the New West; a few hundred each have gone to Minnesota (Tolkeen) and to Ontario and Quebec looking for a fight', 'Humans, Dog Boys, Psi-Stalkers, Quick-Flex Aliens, Tirrvol Sword Fist, and warrior types in general', 'None in particular beyond whoever wants a fight; distrusts Coalition humans after clashes with CS troops and their hired guns, and expects no better of Free Quebec', 'Optional player character. Cowboy, Bounty Hunter, Operator, Vagabond, Wilderness Scout, any Soldier/Military O.C.C., or a Men at Arms O.C.C. from New West other than Psi-Slinger, Wired Gunslinger and CyberSlinger Cyborg. Bionics are usually avoided; M.O.M. and Juicer conversion do not work on them. Gear is the O.C.C.''s with a second heavy weapon added; with no I.S.P. and little P.P.E. they cannot power Techno-Wizard weapons. Few wear armor.', 'A huge, barrel-chested Mega-Damage D-Bee with a long dragon-like head, bony fins along neck, spine, shoulders and elbows, and a snaggle-toothed grin. Most are cheerful, courteous and well liked, and nearly all love a brawl, big guns and adventure.', 'Rifts World Book 20: Canada p.133-134'),
('greot-hunter', 'Greot Hunter', 'humanoid', 'rifts', 1, 'Any, but lean toward Anarchist and evil', '{"IQ":"1D4+5","ME":"1D6+3","MA":"1D6+3","PS":"3D6+20","PP":"2D6+8","PE":"2D6+11","PB":"1D6","Spd":"2D6+7"}', NULL, NULL, '1D6x10+PE', '1D6', NULL, 'M.D.C. is 1D6x10 plus the P.E. number, plus 4D6 per level of experience from level one. Supernatural physical attributes (Supernatural P.S.). Spd is tripled when swimming. On an S.D.C. world: Hit Points 1D6x10 plus P.E., S.D.C. 1D4x10, +2D6 H.P. per level, natural A.R. 12. Heals 3D6 M.D.C. per 12 hours. I.S.P. is not printed.', NULL, NULL, '{"initiative":2,"strike":2,"parry":1,"pull_punch":2,"roll":2}', '+6 to save vs Horror Factor, +3 vs poison and toxins, +5 vs disease, +1 vs magical attacks and possession. All in addition to attribute bonuses. Attacks per melee are those of the Hand to Hand skill plus one for an aggressive nature.', 'Instinctive swimmer: Swim 60% +5% per level of experience.', 'Keen eyesight, great strength and good reflexes. Swims by instinct and withstands depths to 600 feet (183 m). Immune to carcinogens, and blubber under the thick lumpy hide keeps out the cold.', 'None', 'Standard', '7-8 feet (2.1 to 2.4 m) tall', '500 to 600 pounds (225 to 270 kg)', '50 years, although some live to 70', 'Said to come out of the Calgary Rift, which the book doubts, since they are commonest in Manitoba, Ontario and the US Midwest', 'Other strong, warlike beings, above all ones that accept a Greot as boss', 'Humans generally, the CS and Free Quebec in particular, and anyone who stands up to them. Hates N''mbyr Gorilla Men, Psi-Stalkers, Quick-Flex Aliens, Simvan, Vanguard Brawlers and Xiticix; treats Grackle Tooth and Mastadonoids as dangerous rivals; distrusts mages and creatures of magic and goes for them first', 'Optional player character. Combat O.C.C.s only: Bandit, Bounty Hunter, Grunt, Headhunter, Military Specialist, Vagabond, Wilderness Scout, or a Men at Arms O.C.C. from New West. M.O.M. and Juicer conversion do not work on them. Bionics appeal but leave them weaker, so most stop at partial augmentation such as weapon systems. Gear is per O.C.C. Criminal outfits (the Black Market too) often hire them as bodyguards, collectors, enforcers and interrogators.', 'A hulking reptilian or amphibian-looking brute, a born hunter and warrior that ruled its own world and resents sharing this one. Greot are short-tempered, merciless bullies who relish a fight.', 'Rifts World Book 20: Canada p.135'),
('mastadonoid', 'Mastadonoid', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"1D6+6","ME":"2D6+6","MA":"2D6","PS":"3D6+26","PP":"2D6+6","PE":"2D6+6","PB":"1D6+1","Spd":"2D6+6"}', NULL, NULL, '2D4x10+PE', '6D6+12', NULL, 'M.D.C. is 2D4x10 plus the P.E. number, plus 3D6 per level of experience from level one. Supernatural physical attributes (Supernatural P.S.). P.P.E. is 6D6+12; one who takes a magic or Shaman O.C.C. adds only 6D6 as a bonus. On an S.D.C. world: Hit Points 1D6x10 plus P.E., S.D.C. 1D6x10, +1D6 H.P. per level, Natural A.R. 10. Heals 3D6 M.D.C. per 12 hours.', NULL, NULL, '{"initiative":2,"strike":1,"pull_punch":4,"roll":2}', '+1 to save vs magic, +5 vs Horror Factor, +3 vs poison and toxins, +5 vs disease, +4 vs mind control other than demonic possession (to which it is immune). All in addition to attribute bonuses. Attacks per melee are those of the Hand to Hand skill, or one by spell and two physical.', NULL, 'Keen eyesight, great strength and good reflexes. Cannot be possessed by demons. Shaggy fur and blubber make natural cold harmless and halve damage from magical cold. The trunk-like mouth works as a snorkel, and it can dive to 400 feet (122 m) with no gear.', 'Non-mages cast Armor of Ithan, Frost Blade, See the Invisible, Sense Evil, Sense Magic and Throwing Stones; at levels 2, 5, 9 and 12 they add one spell of choice from spell levels 1-3', 'None', '10-12 feet (3 to 3.6 m) tall', '600 to 1000 pounds (270 to 450 kg)', '80-110 years', 'The Arctic and the northern wilds from Alaska to Greenland; some wander south but shun cities and big towns. An estimated 10,000-20,000 exist, most of them in the Arctic', 'No Allies line is printed; the text says they live much like the Inuit, trade news and food with them, and each helps the other', 'Evil supernatural beings, the Windigo most of all; Xiticix; Greot, Loup Garou and other cruel, violent races. Wary of Crazies, Cyborgs, Juicers, pilots of power armor and technology in general', 'Optional player character. Limited to Inuit Shaman; Animal Shaman, Healing Shaman, Mystic Warrior and Tribal Warrior (those four are in Rifts Spirit West); and Bandit, Bounty Hunter, Mystic, Vagabond or Wilderness Scout. No M.O.M. or Juicer conversion, and bionics are avoided. Most live off the land as hunters and steer clear of modern weapons and machines.', 'The Bear Claw People of the Inuit: shaggy tundra giants with an elephant-like head, small tusks, sword-length black claws, and a trunk that is really the mouth. Mighty hunters but neither cruel nor murderous, and still partial to raw meat.', 'Rifts World Book 20: Canada p.137'),
('noli-bushman', 'Noli Bushman', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"2D6+4","ME":"2D6+6","MA":"3D6","PS":"3D6+4","PP":"3D6+2","PE":"3D6+4","PB":"2D6","Spd":"6D6"}', '2D6+PE', '1D4x10', NULL, '3D6', NULL, 'Hit Points are 2D6 plus the P.E. number, plus 1D6 per level of experience from level one (the book prints that per-level gain as ''1D6 M.D.'' on the Hit Points line). S.D.C. is 1D4x10 plus whatever physical skills add. An S.D.C. being: needs magic or M.D.C. armor against M.D. weapons. I.S.P. is not printed in the R.C.C. block (Master Psychic; see the O.C.C.).', NULL, NULL, '{"initiative":1,"strike":1,"pull_punch":4,"roll":2}', '+2 to save vs possession, +3 vs Horror Factor. Saves vs psionic attack and mind control on 10 or better, as a Master Psychic. All in addition to attribute bonuses. Attacks per melee are those of the Hand to Hand skill; a psionic attack uses one melee action.', 'Climb +20% and Prowl +10%.', 'Keen eyesight and nightvision to 300 feet (91.5 m). A thin inner eyelid acts as a built-in polarizing filter, shielding the eyes from glare the way tinted glasses would.', NULL, 'All are in effect Master Psychics, never Mind Melters. A Noli Cowboy or Noli Scout has Bio-Regeneration, Empathy, Mind Block, Psionic Invisibility and Telepathy, two sensitive and two physical powers of choice, one more from either category per further level, and one Super power of choice (not Psi-Sword) at levels 4, 8 and 12', '5 feet, 6 inches to 6 feet (1.7 to 1.8 m) tall', '120 to 160 pounds (54 to 72 kg)', '70-90 years, although a few claim to be older than 120', 'Mostly Ontario, Quebec and the forests of Eastern Canada and the U.S.; a few in Manitoba, Michigan, Illinois and Wisconsin, and now and then anywhere', 'Nothing formal. On good terms with Native Americans, Psi-Stalkers, Simvan, rogue Dog Boys and tolerant humans and D-Bees. Lazlo holds close to 1,000 of them, New Lazlo a few hundred, and 300 have joined Tolkeen', 'The CS and the Quebec military, who have done them great harm; also Greot, Loup Garou, vampires, Xiticix, Yeno and supernatural evil. Wary of other strong psychics, Mind Melters and Mind Bleeders especially, and they stay away from Psyscape', 'Optional player character. Limited to Psi-Druid, Psi-Slayer, Noli Cowboy or Noli Scout; the last two are the Cowboy/Cow Puncher and Wilderness Scout with O.C.C. Related and Secondary skill picks cut to three each and the psionics listed. A Noli may also be a Cyber-Knight (only two are known): Psi-Sword at level one plus six Sensitive and/or Physical powers on top of the usual Knight powers. No M.O.M. or Juicer conversion, and bionics are avoided. Gear is per O.C.C.', 'Greenbeans or Greenies: green-skinned forest humanoids with a long thin neck, a big melon-shaped head and tufts of fur like dreadlocks, who live on bark, roots and other plants. Born woodsmen and strong psychics who are still happy with armor, energy weapons, hovercycles and small towns.', 'Rifts World Book 20: Canada p.137-138'),
('yeno', 'Yeno', 'humanoid', 'rifts', 1, 'Any, but most are Anarchist, Miscreant or Diabolic', '{"IQ":"3D6","ME":"2D6","MA":"2D6","PS":"3D6","PP":"3D6+5","PE":"3D6","PB":"1D6","Spd":"3D6"}', NULL, NULL, '2D4x10+PE', '2D6', NULL, 'Minor M.D.C. creature: 2D4x10 plus the P.E. number, plus 3D6 per level of experience from level one. S.D.C.-world version: Hit Points 1D6x10 plus P.E., S.D.C. 1D6x10, +1D6 H.P. per level, Natural A.R. 10. Separate force field: 30 M.D.C. +10 per level (30 S.D.C. +10 per level on an S.D.C. world).', NULL, NULL, '{"initiative":2,"roll":2}', '+3 to strike with natural energy blasts only. +4 to save vs Horror Factor. All in addition to attribute bonuses. Attacks per melee are those of the Hand to Hand skill, plus two more that may be spent only on natural energy blasts.', NULL, 'Keen eyesight across every spectrum of light. Energy attacks do half damage; kinetic ones (punches, kicks, claws, rail guns, explosives) do full. Fires energy bolts from hands and eyes at a chosen strength, each one a melee attack. Raises a personal force field by thought, 30 M.D.C. +10 per level, kept up as long as it is awake; the field regains 12 points an hour, twice that asleep or meditating. Once knocked down it stays down for an hour or more and comes back at only 12 M.D.C., building hourly.', 'None', 'None, other than the art of meditation', '6 feet (1.8 m) tall', '140 to 180 pounds (63 to 81 kg)', 'Uncertain; at least 200 years, quite possibly longer', 'Commonest in Manitoba, Ontario, Quebec, the Dakotas, Minnesota and Wisconsin, but may turn up anywhere; about a dozen are rumored at Tolkeen and the New West. Fewer than 2000 in all of North America', 'Other cutthroats', 'Whoever crosses them; strong dislike of the CS, Cyber-Knights, Lawmen, Psi-Stalkers and Quick-Flex Aliens. Little regard for life, and they look down on humans and most other races', 'Optional player character. Plays as the counterpart of a Gunslinger, Bounty Hunter, Bandit, Grunt, Spy/Espionage agent, Special Forces, Commando or Assassin. Gear is per O.C.C.; they favor powerful, accurate energy weapons.', 'Energy Weavers or Energy Men: rare, lanky humanoids whose scaly skin is red, orange and yellow, with a melon-shaped head, glowing yellow eyes and three-fingered hands. Permanently foul-tempered and quick to kill, they soak up and throw energy and are notorious as assassins and hired guns.', 'Rifts World Book 20: Canada p.139-140'),
('armored-slayer', 'Armored Slayer', 'monster', 'rifts', 1, 'Any; typically Scrupulous, Unprincipled or Anarchist; a small percentage are evil', '{"IQ":"1D4+5","ME":"2D6+7","MA":"2D6+2","PS":"2D6+22","PP":"2D6+11","PE":"2D6+10","PB":"2D4","Spd":"3D6+16"}', NULL, NULL, NULL, '4D6', 'MEx2+4D6', 'M.D.C. is by location of the built body: hands (2) 100 each, arms (2) 150 each, legs (2) 225 each, head 150, tentacles (6) 20 each, eyes (2) 8 each, main body 300-420 (printed as a range with no dice; 300 is average and 420 the most). The organism inside has M.D.C. of P.E. x2 (on S.D.C. worlds P.E.+2D6 Hit Points and 1D4x10 S.D.C.). On S.D.C. worlds the body''s M.D.C. becomes S.D.C. with a Natural A.R. of 17. P.S. 2D6+22 and Spd 3D6+16 are the armored body; each tentacle has P.S. 1D6+11 and the bare organism Spd 1D4+1. P.P. covers tentacles and body, P.E. is the organism, P.B. both. All physical attributes are Supernatural. I.S.P. gains 1D4 per level for a player character.', NULL, 13, '{"attacks":9,"initiative":3,"strike":3,"parry":6,"pull_punch":6}', '+6 to entangle, +3 to disarm, +6 to save vs Horror Factor, +6 to save vs possession; the parry bonus counts the tentacles. All in addition to attribute bonuses. A tentacle can only be hit by a called shot at -5 to strike, an eye by a called shot at -7.', 'Land navigation 80%, lore: monsters and demons 80%, track animals 60%, track humanoids 65%, swim 40% (+15% out of its armor), climb 60%/40%, prowl 40%, English 70%, and 1D4+1 other languages at 50% (can rise to 70% with experience).', 'Sharp eyes, nightvision 1000 feet (305 m), sees the invisible. Apparently immune to disease, poison and cold, and resistant to heat. Holds its breath one minute per P.E. point and tolerates depths to 1000 feet (305 m), though it dislikes water. The organism heals 3D6 M.D.C. per 12 hours, regrows a tentacle at one foot (0.3 m) a month and an eye in 1D6+6 weeks. Six prehensile tentacles reach ten feet (3 m), work singly or together to strike, parry, entangle, grab and impale, and could hold melee weapons. It builds its humanoid shell from scrap metal, stone and wood bonded with a gray resin it secretes, and has a solvent to take the shell apart: a basic limb at half M.D.C. takes 24 hours and a whole body of 150 M.D.C. takes 72. Damage to the shell does not harm the organism, which can crawl out at will. It feeds on psychic energy: a captured victim is coated in yellow slime and is drained of 1D4x10+60% of its P.P.E., its I.S.P. or both, 100 points at most per feeding; a slimed foe that dies gives up all of its P.P.E.', 'None', 'Mind Block, Meditation, Empathy, Sense Magic, Detect Psionics, Death Trance, Intuitive Combat, Impervious to Cold, Impervious to Fire, Telekinetic Push, Telekinetic Lift, Telekinesis Super', '9-12 feet (2.7 to 3.6 m) tall in its armor; the organism is about 3 feet (0.9 m) tall and 4 feet (1.2 m) long, not counting tentacles', '1500 to 4000 pounds (675 to 1800 kg)', 'Unknown; believed to be 300-600 years', 'Eastern Canada and the eastern US and all around Hudson Bay; now and then Alberta. Usually near large bodies of water, in ruins, forests and marshes; avoids mountains and inhabited cities. Alone, in pairs or in groups of 3-6', 'Inuit, Cyber-Knights and other demon slayers, though few keep company with anyone but their own kind', 'Demons and evil supernatural beings first; Faerie Folk, creatures of magic, mages and psychics are prey (the good-aligned and its own companions may be spared); avoids CS soldiers', 'No O.C.C. An NPC monster that the G.M. may allow as a player character, played as simple, direct and baffled by human society. Uses the Dragon experience table and adds 1D4 I.S.P. per level. Uses no guns, gear or vehicles and wants nothing but scrap for its armor.', 'A tentacled, brain-like alien that lives inside a hulking humanoid shell it glues together from scrap, the way a hermit crab borrows a shell. It drinks psychic energy, hunts demons on instinct, and is far quicker and more agile than its bulk suggests.', 'Rifts World Book 20: Canada p.140-143'),
('black-bear', 'Black Bear', 'animal', 'rifts', 0, 'Anarchist (ordinary bears); a man-eater may be Miscreant', '{"Spd":"22"}', '1D4x10', '3D6+12', NULL, NULL, NULL, 'Spd 22 is 15 mph (24 km); top speed is 44 (30 mph/48 km), held for 2D4 minutes. A.R. is printed as not applicable. No other attributes are printed.', NULL, NULL, '{"attacks":2,"initiative":1,"strike":3,"parry":2}', '+3 to save vs poison and disease.', 'Prowl 35%, track by smell 66%, swim 80%, climb trees 84%.', 'Nightvision 120 feet (36 m). A good swimmer that goes up a tree whenever it is scared or threatened.', 'None', 'None', 'Body 5 to 5.5 feet (1.5 to 1.7 m)', '250-320 pounds (112 to 144 kg)', '18-20 years', 'Forest, mountains and arctic country up to 10,000 feet (3048 m); most of the US and Canada, the eastern half above all', NULL, NULL, 'An animal. Value: fur 150 credits; meat of the whole animal 100-150 credits.', 'A solitary, mostly nocturnal bear that lives on plants, honey, insects, fish, small mammals and carrion, and fattens up in autumn to hibernate. An ordinary S.D.C. animal.', 'Rifts World Book 20: Canada p.143-144'),
('brown-bear', 'Brown Bear', 'animal', 'rifts', 0, 'Anarchist (ordinary bears); a man-eater may be Miscreant', '{"Spd":"22"}', '1D6x10', '3D6+22', NULL, NULL, NULL, 'Spd 22 is 15 mph (24 km); top speed is 50 (35 mph/56 km), held for 3D4 minutes. A.R. is printed as not applicable. No other attributes are printed.', NULL, NULL, '{"attacks":3,"initiative":2,"strike":4,"parry":2}', '+4 to save vs Horror Factor, +2 to save vs poison and disease.', 'Prowl 25%, track by smell 66%, swim 80%, climb 64%.', 'Nightvision 20 feet (6 m).', 'None', 'None', 'Body 5-6 feet (1.5 to 1.8 m)', '600-1000 pounds (272 to 454 kg)', '20-30 years', 'Forest and mountains up to 10,000 feet (3048 m). Mainly the American Northwest and the length of the Rockies (southern Alaska, the Yukon, Northwest Territories, British Columbia, Alberta, Washington, Oregon, Idaho, Montana, Wyoming); less common in the Midwestern US, Saskatchewan and Manitoba; sometimes Ontario, Quebec, Michigan and the eastern US', NULL, NULL, 'An animal. Value: fur 250-350 credits; meat of the whole animal 200 credits.', 'A solitary, day-active bear that eats mostly plants but also takes deer, bison and small game, and hibernates through winter. Threatened or angered, it stands its ground against humans and may fight to the death.', 'Rifts World Book 20: Canada p.144'),
('grizzly-bear', 'Grizzly Bear', 'animal', 'rifts', 0, 'Anarchist (ordinary bears); a man-eater may be Miscreant', '{"Spd":"22"}', '2D4x10', '1D4x10+30', NULL, NULL, NULL, 'The M.D.C. line reads: the equivalent of roughly 1 or 2 M.D.C. Spd 22 is 15 mph (24 km); top speed is 44 (30 mph/48 km), held for 2D4 minutes. No other attributes are printed.', 6, NULL, '{"attacks":4,"initiative":2,"strike":4,"parry":3}', '+6 to save vs Horror Factor, +4 to save vs poison and disease.', 'Prowl 30%, track by smell 68%, swim 70%, climb trees 30% (many are too big and heavy).', 'Nightvision 60 feet (18.3 m).', 'None', 'None', 'Body 6-9 feet (1.8 to 2.7 m)', '800-1800 pounds (363 to 816 kg)', '20-30 years', 'Forest and tundra; essentially the Brown Bear''s range (the American Northwest and the Rockies), and extremely rare in Manitoba, Ontario, Quebec, Michigan and the eastern US. Home range up to 20 square miles (52 sq. km)', NULL, NULL, 'An animal. Value: fur 250-400 credits; meat of the whole animal 300-400 credits.', 'A big, usually solitary bear, yellowish-brown to almost black, active by day or night. It eats plants, fish, small animals and carrion and now and then a deer, horse, bison or humanoid, though most are too slow to run down healthy hoofed prey.', 'Rifts World Book 20: Canada p.144'),
('kodiak-bear', 'Kodiak Bear', 'animal', 'rifts', 0, 'Anarchist (ordinary bears); a man-eater may be Miscreant', '{"Spd":"10"}', '1D4x10+25', '1D6x10+30', NULL, NULL, NULL, 'The M.D.C. line reads: the equivalent of roughly 2-3 M.D.C. Spd 10 is printed as 7 mph (11 km), with no maximum speed given. No other attributes are printed. The heading marks the animal as rare.', 7, NULL, '{"attacks":4,"initiative":3,"strike":5,"parry":2}', '+10 to save vs Horror Factor, +4 to save vs poison and disease.', 'Prowl 35%, track by smell 70% (+20% on a strong scent or blood), swim 70%, climb trees 25% (most are too big).', 'Nightvision, printed as 20 feet (9 m).', 'None', 'None', 'Body 9-14 feet (2.7 to 4.3 m)', '1000-2200 pounds (454 to 998 kg)', '20-30 years', 'Native to the forests of Kodiak Island; also the forests of southern Alaska and the Yukon, seeded by animals that got out of mainland zoos and labs when the Rifts came', NULL, NULL, 'An animal. Value: fur 500-1000 credits; meat of the whole animal 300-500 credits.', 'One of the largest land carnivores, a rare, solitary, day-active bear that is afraid of nothing and that other animals steer clear of. It eats plants, carrion, fish and mammals of any size, people included, and does not normally hibernate.', 'Rifts World Book 20: Canada p.144'),
('polar-bear', 'Polar Bear', 'animal', 'rifts', 0, 'Anarchist (ordinary bears); a man-eater may be Miscreant', '{"Spd":"30"}', '2D4x10+12', '1D4x10+32', NULL, NULL, NULL, 'The M.D.C. line reads: the equivalent of roughly 1 or 2 M.D.C. Spd 30 is 20 mph (32 km); top speed is 58 (40 mph/64 km), held for 2D4 minutes. No other attributes are printed.', 6, NULL, '{"attacks":4,"initiative":3,"strike":4,"parry":3}', '+7 to save vs Horror Factor, +4 to save vs poison and disease.', 'Prowl 50%, track by smell 68% (+12% on a blood scent), swim 98%, climb trees or steep ice 30% (many are too big and heavy).', 'Nightvision 60 feet (18.3 m). A superb swimmer that can stay under for up to five minutes on one breath.', 'None', 'None', 'Body 7-9 feet (2.1 to 2.7 m)', '800-1600 pounds (363 to 720 kg)', '20-30 years', 'Forest and tundra across the Arctic from Siberia and Alaska to Newfoundland and Greenland, down the Pacific coast into the Yukon and British Columbia, and in winter sometimes Alberta and Saskatchewan. Home range up to 50 square miles (130 sq. km); solitary, but 3D4 may gather in mating season', NULL, NULL, 'An animal. Value: fur 350-500 credits; meat of the whole animal 200-300 credits.', 'The most aggressive North American bear and, the rare Kodiak aside, the largest: cream-white with a black nose and claws. It has no fear of people, hunts them as it would seals or caribou, and is drawn to camps by the smell of stored food and garbage.', 'Rifts World Book 20: Canada p.145'),
('mutant-mega-damage-bear', 'Mutant Mega-Damage Bear', 'animal', 'rifts', 0, 'Extremely aggressive; often considered Miscreant or Diabolic', '{}', NULL, NULL, '5D6+23', NULL, NULL, 'M.D.C. 5D6+23 is the Grizzly and the Polar Bear; a Kodiak has 6D6+30. M.D.C. replaces Hit Points and S.D.C. Supernatural P.S. is printed as a range of 16-20 with no dice. Speed is the base animal''s plus 25%, and fatigue is one tenth of normal. Otherwise use the stats of the Grizzly, Kodiak or Polar Bear, always at the top of its size range. The heading marks these as rare.', NULL, NULL, '{}', 'Attacks per melee and bonuses are those of the ordinary animal (Grizzly, Kodiak and Polar Bear each print four attacks).', 'As the ordinary Grizzly, Kodiak or Polar Bear.', 'Supernatural P.S. Heals 1D6 M.D. every 24 hours. Tires at a tenth of the normal rate and moves a quarter faster than the ordinary bear. Other abilities as the base animal.', 'None', 'None', 'The largest size the base animal reaches: Grizzly 9 feet (2.7 m), Kodiak 14 feet (4.3 m), Polar Bear 9 feet (2.7 m)', 'The top of the base animal''s range: Grizzly 1800 pounds (816 kg), Kodiak 2200 pounds (998 kg), Polar Bear 1600 pounds (720 kg)', NULL, 'As the base animal. An estimated 5-7% of Grizzlies and Kodiaks and 10-12% of Polar Bears have turned Mega-Damage', NULL, NULL, 'An animal. No price is printed for the mutant.', 'A Grizzly, Kodiak or Polar Bear changed into a Mega-Damage creature, perhaps by ley line energy or something leaking through a Rift. It is a bigger, tireless, far more savage version of the animal, and many are man-killers.', 'Rifts World Book 20: Canada p.145'),
('red-and-gray-fox', 'Red & Gray Fox', 'animal', 'rifts', 0, NULL, '{"Spd":"44"}', '3D6', '1D6+6', NULL, '2D6', NULL, 'Spd 44 is 30 mph (48 km); top speed is 50 (35 mph/56 km). A.R. is printed as not applicable. No other attributes are printed.', NULL, NULL, '{"attacks":2,"initiative":2,"strike":3,"dodge":4}', '+2 to save vs Horror Factor.', 'Prowl 55%, swim 55%, streetwise 40%, climb trees and rocks 45%, track by smell 55%.', 'Nightvision 120 feet (36 m), sharp eyes and nose. Leaps 3 feet high (printed as 0.9-1.2 m) and 5 feet (1.5 m) across, and can make a leaping pounce as most canines do.', 'None', 'None', 'Body 28-36 inches (0.7 to 0.9 m); tail 12 inches (0.3 m)', '12-25 pounds (5 to 11 kg)', '12-18 years', 'Woods, tundra, grassland, farmland and sometimes towns and cities, all over North America; commonest in the Canadian tundra and the southwest', NULL, NULL, 'An animal. Value: 100-150 credits for the fur and 25-50 for the tail. The meat is not eaten.', 'A clever, adaptable little canine that lives and hunts alone, dens in a burrow, and is as happy raiding a henhouse or a garbage heap as catching birds and rodents. It learns to dodge traps, traffic and watchdogs.', 'Rifts World Book 20: Canada p.145-146'),
('common-gray-wolf', 'Common Gray Wolf', 'animal', 'rifts', 0, NULL, '{"Spd":"50"}', '4D6+6', '2D6+20', NULL, '5D6', NULL, 'Spd 50 is 35 mph (56 km); top speed is 55 (37.5 mph/60 km). A.R. is printed as not applicable. No other attributes are printed.', NULL, NULL, '{"attacks":3,"initiative":3,"strike":5,"dodge":4}', '+5 to save vs Horror Factor.', 'Prowl 50%, track by smell 88%, swim 65%.', 'Nightvision 30 feet (9 m). Scents prey a mile (1.6 km) off. Leap: 3-4 feet (0.9-1.2 m) up, 8 feet (2.4 m) forward; and can make a leaping pounce.', 'None', 'None', 'Body 3 to 4.5 feet (0.9 to 1.4 m); tail 12-19 inches', '50-100 pounds (23 to 45 kg)', '14-20 years', 'Tundra, steppe, open woodland and forest; common across Canada, Alaska, southern Russia and the US. Packs of 6-36', NULL, NULL, 'An animal. Value: fur 40-80 credits. Not edible. Can be partly domesticated but stays dangerous.', 'An intelligent pack hunter that runs down deer, elk, moose and wild horses with its family group, though it often hunts singly or in twos. Pairs mate for life, and its jaws are twice as strong as a domestic dog''s.', 'Rifts World Book 20: Canada p.146'),
('northern-timber-wolf', 'Northern Timber Wolf', 'animal', 'rifts', 0, NULL, '{"Spd":"50"}', '4D6+12', '3D6+24', NULL, '6D6', NULL, 'Spd 50 is about 35 mph (56 km); top speed is 58 (40 mph/64 km). A.R. is printed as not applicable. No other attributes are printed.', NULL, NULL, '{"attacks":3,"initiative":4,"strike":6,"dodge":4}', '+8 to save vs Horror Factor.', 'Prowl 60%, track by smell 90% (+6% on a blood trail or distinct scent), swim 65%.', 'Nightvision 40 feet (12 m). Scents prey a mile (1.6 km) off. Leaps four feet high (printed as 0.9-1.2 m) and 10 feet (3 m) across, and can make a leaping pounce.', 'None', 'None', 'Body 5-6 feet (1.5 to 1.8 m); tail 14-20 inches (0.3 to 0.5 m)', '60-130 pounds (27 to 59 kg)', '14-20 years', 'Forest and steppe; most of Canada, chiefly the northern and southwestern territories and provinces, and the northwestern US from the Dakotas to Washington. Packs of 4-24', NULL, NULL, 'An animal. Value: 60-100 credits for the fur and 10-20 for a complete set of its teeth.', 'A large wolf that prefers moose, elk and deer and mostly keeps away from settlements, though loners do prowl farms and small towns. A pack of ten or more is bold enough to go after livestock, sled dogs and small groups of people; a pack that takes a rider''s horse has only a 01-30% chance of turning on a rider who backs off.', 'Rifts World Book 20: Canada p.146-147'),
('sled-dog', 'Sled Dog', 'animal', 'rifts', 0, NULL, '{"Spd":"44"}', '3D6+10', '2D6+16', NULL, '4D6', NULL, 'Spd 44 is 30 mph (48 km); top speed is 55 (37.5 mph/60 km). A.R. is printed as not applicable. No other attributes are printed.', NULL, NULL, '{"attacks":3,"initiative":4,"strike":3,"dodge":3}', '+5 to save vs Horror Factor.', 'Prowl 45%, track by smell 65%, swim 75%.', 'Nightvision 30 feet (9 m). Leap: 3 feet (0.9 m) up, 6 feet (1.8 m) forward; and can make a leaping pounce.', 'None', 'None', 'Body 3 to 4.5 feet (0.9 to 1.4 m); tail 12-19 inches', '50-80 pounds (23 to 36 kg)', '12-16 years', 'Domestic; Siberia, Alaska and northern Canada from the Yukon to Greenland', 'Inuit and other Indians, trappers, adventurers and Tundra Rangers, who drive them', NULL, 'An animal. Value: 40-70 credits for the pelt; 100-150 credits as a watch or guard dog; 300-500 credits trained to the sled, and 300 more for a seasoned lead dog. A sled needs a team of 7-9.', 'Hardy dogs picked for strong backs, legs and stamina and used to pull sleds over the snowbound tundra from about November through May. Breeds include the Alaskan Malamute, Elkhound, Siberian Husky and Samoyed and their crosses, sometimes even with the Gray Wolf; they are loyal, obedient and glad to work as a team.', 'Rifts World Book 20: Canada p.147'),
('cadborosaurus', 'Cadborosaurus (Caddie)', 'monster', 'rifts', 0, 'Considered an evil predator', '{"IQ":"1D4+3","ME":"1D6+6","MA":"1D6","PS":"2D6+24","PP":"1D6+14","PE":"1D6+20","PB":"1D6"}', NULL, NULL, '3D4x10+PE', '5D6', NULL, 'M.D.C. is 3D4x10 plus the P.E. number. P.S. is Supernatural. Speed is printed only as swimming 25 mph (40 km or 21.5 knots), with no Spd number.', NULL, 13, '{"attacks":4,"initiative":3,"strike":3,"parry":1,"dodge":3}', '+1 to save vs magic, +8 to save vs Horror Factor. All in addition to attribute and special maneuver bonuses. A speed burst gives +2 to a dodge or +2 to a strike on top of the rest.', 'Swim 98%; identify chemicals by taste 65%; track by taste 65%, range one mile (1.6 km).', 'Nightvision 3000 feet (914 m) and sharp color vision. Cold does it no harm. Regenerates 5D6 a day and regrows lost parts in 2D4 months. No depth limit; senses magnetic north as a dolphin does; taste receptors in the mouth read small changes in the water''s salt and chemistry. Water-breathing, and dies after more than 2D4 hours out of water. Stops and turns instantly, dives to 3000 feet (914 m) at double speed, and three times an hour can swim at double speed for 1D4 minutes. Never enters water under 15 feet (4.6 m) deep or comes ashore. Hunts in schools of 3-12 (doubled in mating season) that use real group tactics against ships.', 'None', 'None', '40 to 70 feet (12.2 to 21.3 m) long', '3-6 tons', 'Unknown; believed to be 60 to 120 years', 'The Pacific coast of British Columbia, Washington and Oregon, thickest around Vancouver Island (an estimated 1,800-3,000 there, twice that in May and June); seen from northern California to the Gulf of Alaska', 'None but its own kind; leaves whales and dolphins alone', 'Humans and large aquatic predators', 'No O.C.C.; an NPC monster. Market value: the teeth bring 10-20 credits apiece.', 'The sea serpent of Vancouver Island, a plesiosaur-like animal that the Rifts made a Mega-Damage creature and that now swarms the Pacific coast. It is a dim but patient pack hunter that will shadow a damaged ship for weeks and snatch people off docks.', 'Rifts World Book 20: Canada p.147-149'),
('faerie-bot', 'Faerie Bot', 'humanoid', 'rifts', 1, 'Any, but most are Anarchist', '{"IQ":"1D4+10","ME":"1D4+10","MA":"1D6+10","PS":"1D6+2","PP":"1D6+8","PE":"1D6+10","PB":"1D6+2","Spd":"2D6"}', '2D6+PE', '1D4x10', NULL, '3D4x10', 'MEx10', 'P.P.E. is 3D4x10 plus 10 per level; I.S.P. is M.E. x10 plus 5 per level. Hit Points are 2D6 plus the P.E. number, and the same line adds 1D6 M.D. per level from level one (printed that way, M.D. on a Hit Point line). S.D.C. is 1D4x10 plus any from physical skills; the creature itself is not M.D.C. and needs magic or armor against M.D. weapons. Spd 2D6 is running; the sphere flies at up to 150 mph (240 km), cruising at 10-30 mph (16 to 48 km), and does 60 mph (96 km) on or under water down to one mile (1.6 km). Sphere M.D.C.: main arms (2) 20 each, secondary limbs and tool arms (1-4) 10 each, main body 120 and -3 to strike even on a called shot; it repairs about 40 M.D.C. by itself. Sphere arms have P.S. 1D6+12, secondary limbs 1D4+5. Average NPC level 1D4+4.', NULL, NULL, '{"initiative":1,"strike":1,"pull_punch":4,"roll":2}', '+2 to save vs possession, +3 to save vs Horror Factor; saves vs psionics and mind control on 10 or better as a Master Psychic. All in addition to attribute bonuses. Attacks per melee come from Hand to Hand training, and a psionic attack uses one action.', 'Basic and advanced math, basic electronics, basic mechanics, general repair/maintenance and field armorer at 95%; prowl (in the sphere) and find contraband at 60%; land navigation 70% +2% per level. -35% on artificial intelligences and computers, and cannot hack.', 'Sharp eyes, nightvision 300 feet (91.5 m), and a second eyelid that works as a polarizing filter against glare. A born mechanic: works out how nearly any machine runs, Techno-Wizard devices included, tunes one to go 10-20% faster, and strips, repairs and rebuilds at three times human speed. Sleeps only about three hours a night.', 'Spells at half normal strength, range and duration: Globe of Daylight, Ignite Fire, Fuel Flame, Fire Bolt, Call Lightning, Energy Bolt, Energy Field, Impervious to Energy and Telekinesis, plus two of choice per level from spell levels 1-4', 'Effectively a Master Psychic, limited to Empathy, Object Read, Mind Bolt, Telemechanics, Telemechanic Mental Operation and Telemechanic Paralysis', '8-12 inches (0.2 to 0.3 m) tall; the sphere is about the size of a basketball', '1-2 pounds (0.45 to 0.90 kg); the sphere 40-70 pounds (18 to 31.5 kg)', 'Unknown; possibly immortal', 'Anywhere in North America, mainly southern Canada, Michigan and the Coalition States, wherever technology is thick. Very rare, perhaps only 500 on Earth; groups of 3-12', 'Its own kind and the odd kind, patient human or D-Bee; drawn to Operators, Grackle Tooth and Psi-Techs; likes humans and Sasquatch', 'None as such. Dislikes demons; fears Earth Faerie Folk, dragons and creatures of magic; wary of mages other than Techno-Wizards', 'No O.C.C. is listed. Optional player character at the G.M.''s discretion, starting at first or second level and played as innocent, curious and unreliable around machinery. Standard equipment is the flying sphere: 2-3 main arms, 1-2 secondary limbs, 2-4 tool arms, 1-2 light weapons, a translator at 93%, a 30 foot (9 m) tow line, multi-optics, a proximity alarm and radio. A destroyed sphere takes 1D4+6 months to rebuild.', 'A foot-tall magical humanoid with a shield-shaped head and coal-black eyes that goes everywhere in a basketball-sized flying machine bristling with arms and tools. It is no relation to Earth''s faeries, is obsessed with machines, and tends to leave other people''s gear in pieces.', 'Rifts World Book 20: Canada p.149-151'),
('fury-beetle', 'Fury Beetle', 'monster', 'rifts', 0, 'Anarchist or Miscreant if wild; Unprincipled if properly tamed', '{"IQ":"1D4+3","ME":"1D6+6","MA":"1D6","PS":"2D6+32","PP":"1D6+14","PE":"1D6+20","PB":"1D6","Spd":"2D6x10+40"}', NULL, NULL, '2D4x100', '1D6x10', '1D6x10', 'M.D.C. by location: large front legs (2) 100 each, small legs (28 to 32) 50 each, eyes (11 to 13) 10 each, armor plated head 1D4x100 (printed as 220 on average), main body 2D4x100 (printed as 550 on average for an adult), underbelly 2D4x10+50. On S.D.C. worlds the M.D.C. becomes S.D.C. with a Natural A.R. of 18, and 8 for the soft underbelly. Medium animal intelligence. Supernatural strength and endurance. Spd is running: full speed for 1D6x10 minutes, about half for five or ten, then another burst; runs 24 hours without tiring. Swims at 25 mph (40 km or 21.5 knots).', NULL, 14, '{"attacks":4,"initiative":3,"strike":3,"parry":1,"dodge":1}', '+4 to dodge at a full run, +4 to save vs poison. All in addition to attribute bonuses. An eye can be hit only by a called shot at -5 to strike.', 'Land navigation 80%, track animals or sniff out garbage 60%, track humanoids 30%, swim 75%, climb 80%/20%; follows spoken human language about as well as a horse does.', 'Hawk-sharp sight reaching into infrared and ultraviolet, polarized and thermal vision, nightvision 1000 feet (305 m), sees the invisible. Carries 20 tons with no loss of speed and pulls 40 more at a third speed. Apparently immune to disease and cold and resistant to heat. Heals 4D6 M.D.C. per 24 hours; a small leg grows back in 1D6+6 weeks, an eye takes 1D6+12, and a large foreleg never does. Crosses broken ground easily and swims on the surface. Nervous and easily startled, and once it fights it fights to the death.', 'None', 'Senses and locates water within four miles (6.4 km) automatically at no I.S.P. cost, plus Sense Evil, Sense Magic and Mind Block', '8-10 feet (2.4 to 3 m) tall, a foot (0.3 m) more with spines; 17-20 feet (5 to 6 m) long', '10 to 16 tons', 'Unknown; believed to be 60-90 years', 'Forests of Ontario, Quebec, Newfoundland, eastern Canada and the eastern US, away from cities; over a million there. Simvan have carried some to the New West and Saskatchewan. Dislikes deserts and hot, dry land', 'None; found in groups of 2-8 and small herds of 10-40', 'Humans and big predators such as the Rhino-Buffalo', 'No O.C.C.; an NPC monster and exotic riding animal. Market value: the meat brings 2,000-4,000 credits and the armor plates 4,000-5,000; a trained riding beetle 60,000 to 80,000 credits, at times 15-30% more for an outstanding one. Training has to begin very young and works on only about 55%; adults cannot be broken, and only Simvan ride them. A suit of Fury Beetle plate has 70 M.D.C., weighs 35 lbs (16 kg) and costs about 22,000 credits.', 'A many-legged, spiked, armor-plated alien the size of a semi-truck, named for its jittery zigzag run and its wailing; it is not an insect. Wild ones flatten whatever startles them, while tamed ones serve as mounts, pack beasts and meat.', 'Rifts World Book 20: Canada p.152-154'),
('loup-garou', 'Loup Garou', 'monster', 'rifts', 1, 'Theoretically any; usually Miscreant (36%), Diabolic (40%) or Anarchist (20%)', '{"IQ":"2D6+4","ME":"3D6","MA":"3D6","PS":"4D6+6 min 18","PP":"4D6 min 16","PE":"4D6+6","PB":"3D6","Spd":"5D6"}', '3D4x10+PE', NULL, NULL, '2D4x10+10', '5D6', 'The book prints Hit Points twice: 3D4x10 plus the P.E. number, and then Hit Points (Special) 6D6+36 plus 2D6 per level of experience. The first is recorded. I.S.P. is 5D6 plus 1D6 per level. Spd is 5D6 in human form and 1D6+48 (roughly 35 mph/56 km) as a wolf. Damage is as per Supernatural P.S. No M.D.C.: it is invulnerable rather than Mega-Damage. Average NPC is 1D6 levels.', NULL, 12, '{"attacks":4,"initiative":2,"strike":3,"parry":3,"dodge":3,"pull_punch":3,"roll":2}', 'Four attacks in human or wolf form, six in man-wolf form. +7 to save vs Horror Factor, +2 vs psionics, +2 vs magic. All in addition to attribute bonuses. Horror Factor 12 applies to the man-wolf and giant wolf shapes only, not the human one. Silver weapons (50% silver or more) do double damage straight to Hit Points.', 'Speaks Gobblely, Old Canadian French, and American or Euro at 98%. Land navigation (+20%), track animals (+20%), track humanoids (+25%). Seven Secondary Skills at level one and two more at levels 4, 8, 12 and 15, from Domestic, Espionage, Science, Technical, Pilot (automobile, motorcycle, hover vehicle, boat, horsemanship only), Rogue (+5%, no computer hacking), W.P. (any, leaning to ancient) and Wilderness (+10%).', 'Talks in animal shape. Swim 70% and prowl 80%; sees in the dark to 300 feet (91.5 m); tracks by smell 70% (+15% on a blood scent). Standing leap 15 feet (4.6 m) up and 25 feet (7.6 m) across, half again with a run. Regenerates 4D6 Hit Points an hour. Changes at will among human, giant wolf and wolf-man shapes; a change takes one melee and has no limit on uses or duration. Sleeps only 4-5 hours a day. Immune in every shape to ordinary and Mega-Damage weapons, explosives, fire, cold, poison, drugs, disease and damaging magic; magic that traps, alters surroundings or works on the mind, and mental psionics, still function if it fails its save. Heavy M.D. hits can knock it down or stun it (vampire Knock Down table). Wolfbay and garlic keep it back; crosses, sunlight and running water do nothing. Can wear M.D.C. armor in human shape only. Must be killed twice: slain as a wolf or wolf-man it rises at the next sunrise as a ghoulish human that can no longer change; slain as a human it rises at the next midnight as a wolf-man that has lost half its skills, every language among them, and keeps the rest at half. The ghoulish human likewise has its skills halved. Either survivor has mental attributes down 3, and dies for good when killed in the remaining form.', 'None', 'Sense Evil, Sense Magic, Sixth Sense, See the Invisible, Mind Block', 'Human form 5-6.5 feet (1.5 to 1.9 m) tall; wolf form 4-5 feet (1.2 to 1.5 m) at the shoulders and 7-9 feet (2.1 to 2.7 m) long; man-wolf form seven feet (2.1 m) tall', '200-400 pounds (90 to 180 kg)', '300 years', 'Rare; Eastern Canada (clans in Quebec and Newfoundland, fewer than 400 in all) and Louisiana (an estimated 50-100 in the bayou). Clans run 1D6+2, 2D6+4 or 3D6+8 members', 'Sometimes sides with other supernatural creatures or evil forces; Shifters summon them as assassins', 'Supernatural predators, humans and humanoids; treats the Windigo, D''Sonoqua and Russian Demons as rivals to wipe out', 'R.C.C.: Werewolf, supernatural predator. Headed NPC Monster and Villain and not suggested for players; a G.M. who permits one gets an outcast of Anarchist, Unprincipled or good alignment whom the rest of its kind want dead. The book names two experience tables: the Player Character Experience line says to start at level one on the Dragon table, while the R.C.C. Skills paragraph says to use the Psi-Stalker table.', 'The French-Canadian werewolf, reckoned the cruelest of the werebeasts: a schemer and bully in human shape and a man-hunting killer as a wolf, which hoards trophies and valuables. It has to be destroyed once in each of its forms.', 'Rifts World Book 20: Canada p.155-157'),
('ogopogo-dragon-adult', 'Ogopogo Dragon (Adult)', 'dragon', 'rifts', 0, 'Any; those known on Earth lean toward good', '{"IQ":"2D6+12","MA":"2D6+12","ME":"2D6+9","PS":"2D6+28","PP":"2D6+10","PE":"3D6+10","PB":"3D6+6","Spd":"1D4x10+9"}', NULL, NULL, '1D4x1000+PE', '2D4x100+PE', '1D6x10+40+ME', 'M.D.C. is 1D4x1000 plus the P.E. number, +2D6x100 for an ancient dragon. Supernatural P.S. Spd 1D4x10+9 is crawling on land; swimming is 1D6x10+80. On an S.D.C. world: 1D4x1000 Hit Points, 4D6x100 S.D.C. and A.R. 13 (the A.R. is printed for S.D.C. worlds only). Average NPC level 2D4+4. Major Psychic.', NULL, 16, '{"attacks":7,"initiative":3,"strike":4,"parry":3,"dodge":3,"pull_punch":5,"roll":4}', 'Seven physical attacks per melee or two by magic. +7 to save vs Horror Factor, +3 on all other saves. All in addition to attribute bonuses. Speed Burst gives +2 to a dodge or a strike. Fire magic does 50% more damage when it is out of the water. Ordinary S.D.C. weapons do nothing to it.', 'Basic and advanced math 98%, land and underwater navigation 98%, prowl 40% (+15% underwater), literate in Dragonese/Elven 98%, speaks six more languages at 98%, demon and monster lore 90%, faerie lore 60%, computer operation 92%, plus six picks from Communications, Rogue, Science, Technical, Wilderness and Weapon Proficiencies. Identify chemicals by taste 70%, track by taste 75%.', 'Nightvision 500 feet (152 m), fine color vision that cuts through murky water, sees the invisible and turns invisible at will. Regenerates 1D4x10 M.D.C. a minute. Cold of any kind, magical M.D. cold included, does no damage. Teleport self 75% (+15% to a well known place), dimensional teleport 32% +3% per level, and the other dimensional powers of true dragons. Metamorphosis at will for 4 hours per level, but only into a dark-skinned black-haired human, a large barracuda or a giant salmon. Water spray: 2D4x10 gallons, 01-40% to knock a human-sized target down (initiative and two actions lost), three sprays per gulp, one action each, not usable in human shape. Fresh warm blood burns like acid for one melee round. Unlimited depth tolerance, senses magnetic north, tastes chemical changes in water out to one mile (1.6 km). Breathes air and water but dies after 60 days out of water. Stops and turns instantly; three times an hour swims at double speed for 1D4+2 minutes; dives to 3000 feet (914 m) at double speed.', 'At 8th level or higher: all Water Elemental spells and Wizard spells of levels 1-4, plus 3D4+2 from levels 4-10. At 14th or higher: water spells 1-8, all ice spells and Wizard spells 1-7, plus 3D4+4 from levels 8-15. At 20th or higher: all Elemental water and ice spells, Wizard spells 1-12 and 1D6+4 higher ones. Seldom studies other magic.', 'Major Psychic: all Sensitive powers plus 1D4+2 chosen from either Healing or Physical', '60 to 100 feet (18.3 to 30.5 m) long', '4-6 tons', '6000 years; some reach 10,000', 'The only ones known live in Okanagan Lake and River, British Columbia', 'Beings of like outlook and alignment; the B.C. family likes humans', 'None per se', 'Headed NPC and Villain; the book does not offer it as a player character. The named family in the lake is a 17th level ancient father, an 11th level mother, and young of 8th, 7th, 4th, 3rd and 2nd level.', 'A footless, dark green serpent dragon with a horse-shaped head and a forked tail, the truth behind the old lake monster of the Okanagan. A family of them was stranded on Earth when Atlantis vanished and now guards the towns around the lake.', 'Rifts World Book 20: Canada p.157-160'),
('ogopogo-dragon-hatchling', 'Ogopogo Dragon (Hatchling)', 'dragon', 'rifts', 1, 'Any; those known on Earth lean toward good', '{"IQ":"3D6+2","MA":"4D6","ME":"3D6","PS":"5D6","PP":"3D6+3","PE":"3D6+3","PB":"2D6+3","Spd":"3D6"}', NULL, NULL, '6D6x10+PE', '2D4x10+PE', '1D4x10+ME', 'M.D.C. is 6D6x10 plus the P.E. number. P.P.E. is 2D4x10 plus P.E., +10 per level of experience. Spd 3D6 is crawling on land; swimming is 6D6+30. On an S.D.C. world: 1D4x100 Hit Points, 4D6x10 S.D.C. and A.R. 9 (the A.R. is printed for S.D.C. worlds only). Average NPC level 1D4. Minor psionic. The Supernatural P.S. remark is printed on the adult attribute line.', NULL, 12, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"dodge":1,"pull_punch":2,"roll":2}', 'Four physical attacks per melee or one by magic. +3 to save vs Horror Factor, +1 on all other saves. All in addition to attribute bonuses. Speed Burst gives +2 to a dodge or a strike. Fire magic does 50% more damage when it is out of the water. Ordinary S.D.C. weapons do nothing to it.', 'The R.C.C. skill list is printed once for both ages: basic and advanced math 98%, land and underwater navigation 98%, prowl 40% (+15% underwater), literate in Dragonese/Elven 98%, six more spoken languages at 98%, demon and monster lore 90%, faerie lore 60%, computer operation 92%, plus six picks from Communications, Rogue, Science, Technical, Wilderness and Weapon Proficiencies. Identify chemicals by taste 70%, track by taste 75%. Recognizes magic circles and enchantment at 40% +5% per level.', 'The natural abilities are printed once for both ages. Nightvision 500 feet (152 m), sees through murky water, sees the invisible and turns invisible at will. Regenerates 1D4x10 M.D.C. a minute. Immune to cold, magical M.D. cold included. Teleport self 75% (+15% to a well known place), dimensional teleport 32% +3% per level. Metamorphosis at will for 4 hours per level, limited to a dark-skinned black-haired human, a large barracuda or a giant salmon. Water spray of 2D4x10 gallons with a 01-40% knockdown, three sprays per gulp. Fresh warm blood burns like acid. Unlimited depth tolerance, senses magnetic north, tastes chemical changes out to one mile (1.6 km). Breathes air and water but must get back to water within 60 days. Swims at double speed for 1D4+2 minutes three times an hour; dives to 3000 feet (914 m).', 'Understands magic fully but starts with no spells; learns them as easily as a first level Wizard and typically has 3D4+2 Wizard spells of levels 1-3 by second level. Uses any magic device by instinct, reads magic and uses scrolls.', 'Minor psionic: six powers chosen from either Sensitive or Healing, and two more at levels 4, 8, 12 and 16', '60 to 100 feet (18.3 to 30.5 m) long (one size line is printed for both ages)', '4-6 tons (one weight line is printed for both ages)', '6000 years; some reach 10,000', 'The only ones known live in Okanagan Lake and River, British Columbia', 'Beings of like outlook and alignment; the B.C. family likes humans', 'None per se', 'Headed NPC and Villain and never called an optional player character, although the hatchling psionics line lets the player or G.M. choose the powers. NPC hatchlings over 100 years old have spells; the lake family''s three youngest are hatchlings of 2nd to 4th level, about 190 years old.', 'The young of the Okanagan lake dragon: a serpent with a horse-like head. It has its parents'' water powers but has barely begun to learn magic.', 'Rifts World Book 20: Canada p.157-160'),
('spirit-sasquatch', 'Spirit Sasquatch', 'spirit', 'rifts', 0, 'Typically Scrupulous (60%) or Principled (30%); sometimes Anarchist (6%), Aberrant (2%) or other (2%)', '{"IQ":"2D6+6","ME":"2D6+14","MA":"2D6+6","PS":"3D6+22","PP":"2D6+10","PE":"2D6+10","PB":"2D6+4","Spd":"3D6+12"}', NULL, NULL, 'PEx5', 'PEx5', 'MEx3', 'M.D.C. is P.E. x5 plus 2D6 per level of experience; P.P.E. is the same. I.S.P. is M.E. x3 plus 6 per level. All attributes are supernatural. On S.D.C. worlds: Hit Points P.E. x2 +1D6 per level, S.D.C. P.E. +1D6x10, Natural A.R. 12 (the A.R. is printed for S.D.C. worlds only). Average level 1D4+4.', NULL, 11, '{"attacks":6,"initiative":2,"strike":2,"parry":1,"dodge":1,"roll":2,"pull_punch":3}', 'Six hand to hand or psionic attacks per round for one relying on natural abilities, +1 at levels 6 and 12; one with an O.C.C. uses that O.C.C.''s combat instead. +1 to save vs magic, +5 to save vs Horror Factor. All in addition to attribute and any O.C.C. bonuses.', 'Land navigation, wilderness survival, identify plants and fruits, track animals, track humanoids, skin and prepare animal hides, palming, swim, climb, lore: animal/cattle and detect ambush, all at 85%, plus any O.C.C. skills.', 'Nightvision, infrared and thermal vision, each 1000 feet (305 m). Sharp sight, hearing and smell: tracks by smell 40% +5% per level and knows a scent at 30% +4% per level. Cannot be poisoned, sickened, chilled or possessed, and does not tire; regenerates 2D6 M.D.C. each melee round. Minor Dimensional Doorway: a short teleport for itself and whatever it carries to a spot it can plainly see, once a day per level, reaching 100 feet (30.5 m), and 20 feet (6 m) farther for each level, one melee action and 10 P.P.E. per use; aiming at ground it cannot see leaves it in mid-air. Can be hurt by magic, psionics and M.D. weapons. Shuns cities, crowds, cramped places and open country. Never uses modern weapons, armor, gear or vehicles.', 'Natural powers: Death Trance, Chameleon, Shadow Meld, Escape, Concealment, Detect Concealment, Dowsing, Repel Animals, Mystic Fulcrum, Create Water, Frost Blade, Purification of food and water', 'Mind Block, Total Recall, See the Invisible, Sense Evil, Sense Magic, Sense Dimensional Anomaly, Exorcism', '9-12 feet (2.7 to 3.6 m) tall', '250 to 400 pounds (112.5 to 180 kg)', 'Immortal', 'Forests, mountain forests above all, of the western USA and Canada: British Columbia, the Yukon, Washington, Oregon and the Rockies. Never on prairie, tundra, farmland or in towns. Always met alone', 'True Sasquatch and animals; now and then Nature Spirits and Indian Gods. Never its own kind', 'Demons, which it attacks whenever the odds allow; those who kill for sport or wreck the forest are driven off rather than slain', 'NPC only: the book says this lesser supernatural being is not meant as a player character. About 40% match a Shaman (Plant, Animal or Elemental) or a Warrior (Tribal or Totem) (as Rifts Spirit West, without Secondary Skills); the others use only natural abilities and R.C.C. skills. Carries a war club, staff or tomahawk and wears a loincloth with some bone or wood armor. Owns no valuables.', 'A towering fur-covered woodland spirit, taller and heavier-browed than the mortal Sasquatch it is mistaken for, that appoints itself guardian of the forest. It frightens and sabotages despoilers rather than killing them, and saves its real violence for demons.', 'Rifts World Book 20: Canada p.160-162'),
('true-sasquatch', 'True Sasquatch', 'humanoid', 'rifts', 1, 'Typically Principled (45%), Scrupulous (35%) or Unprincipled (15%); Anarchist (3%) and evil (any, 2%) are rare', '{"IQ":"2D6+4","ME":"2D6+4","MA":"3D6+4","PS":"3D6+10","PP":"3D6+2","PE":"3D6+4","PB":"2D6+4","Spd":"3D6+8"}', NULL, NULL, 'PEx2', 'PE+4D6', NULL, 'M.D.C. is P.E. x2 plus 1D6 per level of experience. P.P.E. is the P.E. number plus 4D6, +6 per level. No I.S.P. figure is printed although every Sasquatch is psionic. P.S. and P.E. are supernatural. An attribute roll that comes up maximum (12 or 18) earns one extra die before the bonus is added. On S.D.C. worlds: Hit Points P.E. +1D6 per level, 1D4x10+30 S.D.C., Natural A.R. 7 (the A.R. is printed for S.D.C. worlds only). Average level 1D4+3.', NULL, 9, '{"attacks":2,"initiative":3,"parry":1,"pull_punch":5,"roll":2}', 'Two actions per melee at level one, +1 at levels 2, 4, 7, 10 and 13. +3 to disarm. +1 to automatic dodge (costs no action) at levels 2, 4, 6, 8, 10, 12 and 14. +2 to save vs disease and toxins, +2 vs possession and mind control. Fights only to get away and almost never kills.', 'Male: land navigation 90%, wilderness survival 90%, identify plants and fruits 90%, swim 65%, climb 80%/50%; lore: animal/cattle, camouflage and prowl at 74% +2% per level; track animals 55% and track humanoids 45% (these two do not improve). Female: land navigation 90%, wilderness survival 90%, identify plants and fruits 90%, fishing 80%, swim 65%, climb 70%/40% +2% per level; holistic medicine, first aid, lore: animal/cattle, camouflage and prowl at 60% +2% per level. Most have no spoken language but can learn one.', 'Nightvision 300 feet (91.5 m); sharp sight, hearing and smell (tracks by smell 40% +2% per level, knows a scent at 30% +4% per level). Takes half damage from cold and heals twice as fast as a human. Speaks mind to mind with other Sasquatch only, up to three at once, within 600 feet (183 m) at no I.S.P. cost. Among themselves they also use whistles, grunts, gestures and empathy. Eats plants, fish, grubs and honey; uses no tools, fire, clothing or weapons. In a city it breaks down (attacks, bonuses and skills halved) in half the time a Worldly Sasquatch takes, which is 26 hours +1 per M.E. point.', 'None; will never learn it', 'Male: Empathic Transmission (Confusion, Fear and Love/Peacefulness only), Psionic Invisibility, Alter Aura, Deaden Senses, See the Invisible, Empathy, Sense Evil; Radiate Horror Factor at level 2, Intuitive Combat at level 4, Psychic Omni-Sight at level 8. Female: Sense Dimensional Anomaly, Sense Time, Empathy, See the Invisible, Sense Evil, See Aura, Psychic Diagnosis, Psychic Purification, Psychic Surgery and two Healing powers of choice; one more Healing power at levels 3, 6, 9 and 12, Bio-Regenerate (self) at level 5 and one Sensitive power at level 8. Both: Special Telepathy with their own race.', '7-8 feet (2.1 to 2.4 m)', '250 to 400 pounds (112.5 to 180 kg)', '50 years', 'Thickest in the Canadian Rockies of British Columbia and Alberta and the deep woods of Washington, Oregon and Montana; fewer in the Yukon, Idaho, Wyoming, Northern California and Colorado. Over ten thousand in all, wandering in family groups of two to ten', 'Other Sasquatch and the Spirit Sasquatch; now and then an Indian Shaman, Druid, psychic or a kindly adventurer', 'None per se, though every outsider is treated as a possible threat; hates, fears and avoids supernatural beings', 'Headed NPC and Optional Player Character. Available O.C.C.s: None (the Worldly Sasquatch O.C.C. on p.166 is a separate class for one that joins the wider world). No cybernetics, no money and almost no gear. A human or D-Bee child raised by them gets the same skills plus 1D4+1 from Wilderness and/or Physical, but none of the natural or psionic abilities.', 'The real Big Foot: a shy, gentle Stone Age cousin of humanity that walked over the Bering land bridge long ago and has hidden in the mountain forests ever since. The Rifts made it a minor Mega-Damage being, and it still answers any threat by slipping away.', 'Rifts World Book 20: Canada p.162-165'),
('typical-dinosaur-small', 'Typical Dinosaur (Small)', 'monster', 'rifts', 0, NULL, '{"Spd":"6D6"}', NULL, NULL, '6D6+24', '3D6', NULL, 'M.D.C. is 3D6 for one smaller than a dog and 6D6+24 for one nearer man-size; the man-size figure is recorded. Speed 6D6, +10 for predators. No other attributes are printed; strength and endurance are simply called high.', NULL, NULL, '{}', 'Attacks per melee: two for a herbivore, three for a carnivore.', 'Track by smell 60% (+2D6% for predators).', 'Great stamina and strength and a sharp nose that picks up blood from as far as four miles (6.4 km). Two-legged kinds can jump 10 feet (3 m) up and clear 20-30 feet (6-9 m).', NULL, NULL, 'From smaller than a dog to about human size', NULL, NULL, 'The New West and southwestern Canada (mainly B.C., Alberta and Saskatchewan), Florida and elsewhere', NULL, NULL, 'A G.M. design template, not a named species; no value is printed. Some kinds serve as riding animals or as meat.', 'The smallest tier of the book''s build-your-own outline for Mega-Damage dinosaurs, covering anything from dog-sized up to roughly a person. Numbers differ for plant-eaters and meat-eaters.', 'Rifts World Book 20: Canada p.168-169'),
('typical-dinosaur-medium', 'Typical Dinosaur (Medium)', 'monster', 'rifts', 0, NULL, '{"Spd":"1D6x10+8"}', NULL, NULL, NULL, '3D6', NULL, 'M.D.C. is printed as 6D6+6 for smallish ones and 2D4x10+34 for large ones, with no single figure for the class, so the field is left empty. Speed 1D6x10+8. No other attributes are printed; strength and endurance are simply called high.', NULL, NULL, '{}', 'Attacks per melee: two for a herbivore, five for a carnivore.', 'Track by smell 60% (+2D6% for predators).', 'Great stamina and strength and a sharp nose that picks up blood from as far as four miles (6.4 km). Two-legged kinds can jump 10 feet (3 m) up and clear 20-30 feet (6-9 m).', NULL, NULL, '10 to 20 feet (3 to 6.1 m)', NULL, NULL, 'The New West and southwestern Canada (mainly B.C., Alberta and Saskatchewan), Florida and elsewhere', NULL, NULL, 'A G.M. design template, not a named species; no value is printed. Some kinds serve as riding animals or as meat.', 'The middle tier of the book''s build-your-own outline for Mega-Damage dinosaurs. It splits damage between plant-eaters and lesser hunters on one side and big predators on the other.', 'Rifts World Book 20: Canada p.168-169'),
('typical-dinosaur-large', 'Typical Dinosaur (Large)', 'monster', 'rifts', 0, NULL, '{"Spd":"1D6x10"}', NULL, NULL, '1D4x100', '5D6', NULL, 'M.D.C. 1D4x100 is the main body. Speed 1D6x10. No other attributes are printed; strength and endurance are simply called high.', NULL, NULL, '{}', 'Attacks per melee: three for a herbivore, four for a predator. Special defenses or natural weapons may do one die more.', 'Track by smell 60% (+2D6% for predators).', 'Great stamina and strength and a sharp nose that picks up blood from as far as four miles (6.4 km). Two-legged kinds can jump 10 feet (3 m) up and clear 20-30 feet (6-9 m).', NULL, NULL, '30 to 50 feet (9.1 to 15.2 m)', NULL, NULL, 'The New West and southwestern Canada (mainly B.C., Alberta and Saskatchewan), Florida and elsewhere', NULL, NULL, 'A G.M. design template, not a named species; no value is printed. Some kinds serve as riding animals or as meat.', 'The giant tier of the book''s build-your-own outline for Mega-Damage dinosaurs, for beasts thirty feet long and up. Plant-eaters and predators get separate attack counts and bite and claw damage.', 'Rifts World Book 20: Canada p.168-169'),
('demon-bear', 'Demon Bear', 'demon', 'rifts', 0, 'Diabolic', '{"IQ":"1D4+6","ME":"1D6+6","MA":"1D6","PS":"2D6+40","PP":"1D6+14","PE":"1D6+14","PB":"1D6+6","Spd":"3D6+40"}', NULL, NULL, 'PEx8', '1D6x10+40', NULL, 'M.D.C. is P.E. x8. Hit Points (P.E. x5) and S.D.C. (P.E. +1D6x10) with Natural A.R. 12 apply on S.D.C. worlds only. All attributes are supernatural. Regenerates 4D6 M.D.C. per melee round.', NULL, 14, '{"attacks":5,"initiative":3,"strike":4,"parry":1,"dodge":1,"roll":2,"pull_punch":2}', 'Five physical attacks per melee or two by spell. +2 to dodge underwater (instead of +1). +10 to save vs Horror Factor. -4 to save vs all magic. All bonuses are in addition to attribute bonuses.', 'Land navigation, wilderness survival, track animals, track humanoids and swim at 80% (+10% on a blood trail); climb 60%/40%; prowl 50%.', 'Nightvision 1000 feet (305 m); sharp sight, hearing and smell (track by scent 65%, know a specific scent 50%). Holds breath one minute per P.E. point and survives depths to 1000 feet (305 m). Immune to poison, disease, ordinary cold and possession; never tires. Regrows limbs in 24 hours and the whole body in 48 unless beheaded and the head or body burned or cast into the sea. Understands every Indian language but speaks none. Vulnerabilities: magic weapons (cold magic included) do full damage; rune weapons and Millennium Tree weapons do double; Psi-Sword and most psionics do normal damage; most conventional M.D. weapons do half; stone S.D.C. weapons, sling stones and baseball-sized thrown rocks do their damage as M.D. Slaying or exorcising the bear banishes the entity for centuries.', 'Turn Invisible (self), Chameleon, Fingers of the Wind, Fear, Repel Animals, See the Invisible, Sense Magic', 'None', '10-15 feet (3 to 4.6 m) tall standing erect; the host bear grows 20-40%', '1000+ pounds (450 kg)', 'The entity is immortal and leaves the moment its host is killed; a Demon Bear can last decades but most are hunted down fast', 'Arctic and tundra: Alaska, the Yukon, Northwest Territory, Nunavut; in winter the north of British Columbia, Alberta, Saskatchewan and Manitoba; once a decade or two down the Rockies into Washington, Idaho or Montana', 'Other Demon Bears, Windigo, Sedna the Sea Hag, greater demons, the odd evil Shifter, Witch or Necromancer', 'Every mortal creature, human or animal; practitioners of magic above all', 'NPC monster, a Lesser Demon; no O.C.C. Carries no gear or valuables.', 'A killing entity that possesses a polar, grizzly or brown bear and turns it into an oversized Mega-Damage monster that murders people, livestock and wildlife for the joy of it. Usually hunts alone and shows up in the winter months.', 'Rifts World Book 20: Canada p.170-172'),
('dsonoqua-the-cannibal-woman', 'D''Sonoqua, the Cannibal Woman', 'demon', 'rifts', 0, 'Miscreant or Diabolic', '{"IQ":"1D6+7","ME":"1D6+7","MA":"1D6+7","PS":"1D6+17","PP":"1D6+17","PE":"1D6+17","PB":"1D6+3","Spd":"1D6+17"}', NULL, NULL, '2D4x10+PE', '60+PE', NULL, 'M.D.C. is 2D4x10 plus the P.E. attribute number. Hit Points (P.E. +1D6x10) and S.D.C. (1D4x10+17) with Natural A.R. 9 apply on S.D.C. worlds only. P.P.E. is 60 plus the P.E. attribute number. All attributes are supernatural. Regenerates 1D6 M.D. per minute.', NULL, 11, '{"attacks":5,"initiative":1,"strike":2,"parry":1,"dodge":1,"roll":1,"pull_punch":5}', 'Five physical attacks per melee or two by spell. +7 to save vs Horror Factor. Horror Factor 11 applies only once she shows her true nature. All bonuses are in addition to attribute bonuses.', 'All domestic skills 90%; first aid, holistic medicine, brewing, animal lore, land navigation, wilderness survival, track humanoids, prowl and palming 75%.', 'Nightvision 300 feet (91.5 m). Immune to poison, disease, ordinary cold and possession; tires at a tenth of the human rate. A lost limb is replaced by stitching on one from a fresh corpse, which is hers within 24 hours. Vulnerabilities: cannot swim and drowns after five-plus minutes held under; full damage from magic and magic weapons, conventional M.D. weapons do half, S.D.C. weapons do nothing. Sleeps only 4 hours a day.', 'Sense Evil, Chameleon, Tongues, Negate Poison, Healing Touch, Greater Healing, Cure Illness, Purification (food/water), Calling, Befuddle, Fear, Magic Net, Blind, Mute, Agony, Spoil, Sickness', 'None', '5-6 feet (1.5 to 1.8 m) tall', '100-150 pounds (45 to 68 kg)', '317 years', 'Siberia, Alaska and anywhere in Canada, mostly cold and remote places; rarely the US', 'One or two henchmen (a human or lesser demon, always Miscreant or Diabolic) and now and then other powerful evil beings; otherwise a loner', 'Humans and all intelligent life, the good most of all; steers clear of mages and Shamans for fear of exposure and flees to a new lair if found out', 'NPC monster, a rare Lesser Demon; no O.C.C. A human woman becomes one through a pact with a dark god or Alien Intelligence. Keeps victims'' belongings at home or in a hidden lair, but uses no M.D. gear herself except a Vibro-Blade or magic items.', 'A pale, white-haired hag who plays the kindly old healer to lure children and lost travelers, then enslaves and eats them. She typically holds 1D4+2 child slaves and 1D4 caged captives.', 'Rifts World Book 20: Canada p.172-173'),
('sedna-the-sea-hag', 'Sedna, the Sea Hag', 'demon', 'rifts', 0, 'Anarchist, mean and cruel', '{"IQ":"19","ME":"8","MA":"3","PS":"40","PP":"22","PE":"22","PB":"2","Spd":"132"}', NULL, NULL, '3900', '4200', NULL, 'Fixed numbers for a unique being. M.D.C. 3,900; the 5,000 Hit Points and 2,500 S.D.C. apply on S.D.C. worlds only, with Natural A.R. 10 on dry land and 15 in or under water. P.P.E. 4,200. Spd 132 is about 90 mph (148 km). All attributes are supernatural. In human form her physical attributes, M.D.C., P.P.E. and combat bonuses are halved. Regenerates 6D6 M.D. per melee round, half on dry land.', NULL, 19, '{"attacks":5,"initiative":4,"strike":3,"parry":2,"dodge":3,"roll":2,"pull_punch":4}', '+6 to dodge underwater (instead of +3). +1 to save vs magic, +5 to save vs Horror Factor, immune to possession. Horror Factor 19 in true form, 15 in human form. Natural A.R. 15 in or under water. All bonuses are in addition to attribute bonuses and are halved in human form.', 'Astronomy, navigation, land navigation, basic mathematics, boat building, pilot sail and row boats (canoes included) and lore: demons and monsters, all 98%. Swim 98%. Speaks all languages 90%, cannot read.', 'Tireless runner and swimmer; needs no air and ignores any water pressure. Nightvision one mile (1.6 km), sees the invisible, dimensional teleport 40% (+20% at a nexus). Water link: identify minerals 50%, aquatic life 98%, time and direction from sky and tide 98%, sense winds, currents, tides and undersea disturbances 98%, sense coming waves and storms 98%, sense impurities in water 90%, sees through fog, dowsing at triple the spell''s range. Commands the animals of the sea, polar bears included. Visage: anyone seeing her true form has a 01-80% chance of insanity and a phobia of northern waters (01-65% for non-Inuit Shamans and Druids, 01-45% and +2 to save vs Horror Factor for children and maidens under 21; the Inuit Shaman is immune); lesser and many greater supernatural beings flee or obey. Her human shape is an avatar; if it is slain a gasping fish is left, and she takes revenge unless it is put back in water. Immune to depth, drowning, waves, lightning, cold and ice (magical too), disease, storm winds, toxins and ordinary S.D.C. attacks; S.D.C. weapons of sea-animal bone or tooth do their damage as M.D.; falls and kinetic attacks do half; M.D. weapons, magic and psionics do normal damage. Slain in spirit form she returns the next Spring.', 'All water, ice and cold spells including all Water Warlock spells, plus Rainbow (Air Warlock), Fingers of the Wind, Float in Air, Escape, Globe of Daylight, Globe of Silence, Energy Bolt, Call Lightning, Electrical Arc, Lightning Arc, Desiccate the Supernatural, Turn Dead (20x as many), Animate and Control the Dead (10x as many), Sheltering Force, Summon Fog, Summon Rain, Summon Storm, Calm Storm, Summon & Control Sea Serpents, Second Sight, Oracle, Cleanse, Sustain, Negate Poison, Healing Touch, Greater Healing, Restore Limb, Restore Life, Remove Curse. Spell potency of an 8th level sorcerer.', 'None', '20 feet in true form; 6 feet (1.8 m) tall as a human', 'Five tons in true form; 120 pounds (54 kg) as a human', 'Immortal', 'The Arctic Ocean and nearby waters from Siberia to Greenland; now and then the far north of Siberia, Alaska, the Yukon, Northwest Territories, Nunavut and the northern islands and ice', 'Relies on herself; commands sea creatures and polar bears, sometimes works through Inuit Shamans and people who have earned her favor. Demon Bears and Windigo fear and obey her.', 'Anyone, mortal or not, who bothers, crosses or challenges her; dislikes most intelligent life, demons and destroyers especially', 'Unique NPC, a god-like sea spirit; no O.C.C. Also called Nuligajuk, Nulijajuk, Adlirqpat and Sea Mother. Value: none. Only the Angakoq can speak with her directly; a respectful ceremony may win calm seas, a better catch (1D4x10% more) or a storm turned aside.', 'The fickle and spiteful Inuit mistress of the sea, a hideous immortal who rules the Arctic waters and the drowned Land of the Dead. She walks ashore as a gaunt blue-white hag and rewards respect and kindness as readily as she punishes disgust.', 'Rifts World Book 20: Canada p.174-176'),
('windigo-demon', 'Windigo Demon', 'demon', 'rifts', 0, 'Always Diabolic', '{"IQ":"1D6+2","ME":"1D6+6","MA":"1D6+6","PS":"2D6+32","PP":"1D6+16","PE":"1D6+16","PB":"1D6","Spd":"2D6+12"}', NULL, NULL, '4D4x10+PE', '1D4x10+30', NULL, 'M.D.C. is 4D4x10 plus the P.E. attribute number. Hit Points (P.E. x5) and S.D.C. (P.E. +1D4x10+20) with Natural A.R. 12 apply on S.D.C. worlds only. Spd 2D6+12 is walking upright; add 40 running on all fours (about 38 mph/61 km on average). All attributes are supernatural. Low I.Q. but a cunning, instinctive predator. Regenerates 2D6 M.D.C. per melee round.', NULL, 13, '{"attacks":6,"initiative":4,"strike":4,"parry":2,"dodge":2,"roll":2,"pull_punch":4}', '+10 to save vs Horror Factor. Horror Factor 13 for one, 15 for a pack. A starving Windigo has half its combat bonuses and one attack fewer. All bonuses are in addition to attribute bonuses.', 'Land navigation, wilderness survival, track animals, track humanoids and swim at 90% (+5% on a blood trail); detect ambush 60%; climb 70%/60%; prowl 55%. Understands all spoken languages; speaks English/American, French and all Native American tongues at 55%; reads none.', 'Nightvision 2000 feet (610 m), sees the invisible, sharp sight, hearing and smell: track by scent 75% (+15% on blood, smelled up to two miles/3.2 km off), know a specific scent 65%. Never tires; regrows limbs in 72 hours and the whole body by the following full moon if its skull is left intact. Goes three weeks without food at no penalty and cannot starve to death. Immune to poison, disease, ordinary cold and S.D.C. weapons; magical cold does one third. S.D.C. weapons of silver or of sea-animal bone or tooth do their damage as M.D. Paralyzing scream: hearers save vs magical Horror Factor 13 or freeze, defenseless, for 1D4 melee rounds (Juicers, Crazies and partial or full cyborgs +2 to save); those who save lose initiative for one round. The book says both that M.D. weapons, explosives, magic weapons, spells and psionics do half damage and that magic and magic weapons do full.', 'None', 'None', '12-16 feet (3.6 to 5 m)', '1000+ pounds (450 kg)', 'Effectively immortal; only violent death with the skull smashed kills it', '1-10 can turn up anywhere in Canada; most common in the northern forests and tundra, favoring forest and mountains. Solitary or in packs of 2D4+1', 'Other Windigo, Demon Bears, and at times other powerful dark forces; never a mere mortal', 'All humans are prey; Cyber-Knights, Shamans, Druids, practitioners of magic and Psi-Stalkers are mortal enemies; enjoys hunting the good and self-styled heroes', 'NPC monster, a lesser demon; no O.C.C. Uses no tools or weapons of man; a lair may hold skulls, gems and jewelry worth no more than 1D6x1000 credits. An utterly evil mortal who pledges himself to the Windigo God becomes one at the next full moon, losing all memory and skills, irreversibly.', 'A gaunt, red-furred giant with a hairless skull-white face and glowing red eyes that hunts and eats humanoids, alone or in wolf-like packs. Also called Wendigo, Witiko, Weeketow and Demon Sasquatch.', 'Rifts World Book 20: Canada p.176-178'),
('wishpoosh-the-demon-beaver', 'Wishpoosh, the Demon Beaver', 'demon', 'rifts', 0, 'Miscreant', '{"IQ":"1D4+6","ME":"1D6+2","MA":"1D4","PS":"2D6+30","PP":"1D6+10","PE":"1D6+20","PB":"1D6+2","Spd":"2D6+20"}', NULL, NULL, '1D6x10+120', '2D4x10+PE', NULL, 'Hit Points (3D4x10) and S.D.C. (70) with Natural A.R. 10 apply on S.D.C. worlds only. P.P.E. is 2D4x10 plus the P.E. attribute number. P.S. and P.P. are doubled in water and Spd is tripled swimming. All attributes are supernatural. Regenerates 1D6 M.D.C. per melee round.', NULL, 10, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"dodge":1}', 'Four physical attacks per melee or one by spell. Underwater: +3 on initiative, +4 to strike, +3 to parry and dodge. +6 to save vs Horror Factor. All bonuses are in addition to attribute bonuses.', 'Wilderness survival, fishing and swim 95%; land navigation, carpentry and boat building 80%; prowl 40% (+20% in water). Speaks all languages 90%, cannot read.', 'Nightvision 2000 feet (610 m) and clear sight in murky water, but in bright light sees only 300 feet (91.5 m). Holds breath 30 minutes per P.E. point and survives depths of two miles (3.2 km); never tires. Rides any wave unharmed and walks or runs on water at normal speed. Fells a full-grown tree in 1D4 minutes, a young one in 1D4 melee rounds, a sapling in one action. Builds 20 square feet (1.8 sq. m) of dam an hour and can direct ordinary beavers. Make Waves: tail slaps, taking every action of the round, double existing waves or raise six foot (1.8 m) ones, lasting a further minute per minute used; free once per 24 hours, 50 P.P.E. after that. Immune to disease, drowning and normal S.D.C. weapons; resists cold, possession and magic. Maple-wood S.D.C. weapons do their damage as M.D.; Millennium Tree weapons do double; magical fire does 50% more; lightning, electricity, cold and water magic do half; underwater explosives do nothing. Chokes on maple seeds and acorns. The book says both that man-made M.D. weapons do normal damage and that most do half.', 'Summon & Control Animals (beavers and frogs only), Repel Animals, Seal, Sense Magic, Mystic Fulcrum, Mend the Broken, Create Water', 'None', '15 feet (4.6 m) snout to rump, plus an eight foot (2.4 m) tail', '2000+ pounds (900 kg)', 'Uncertain, 1000+ years; probably immortal', 'Cool country full of lakes, rivers and forest: New Brunswick, Quebec, Ontario, Manitoba, British Columbia, Washington, the Dakotas, Minnesota, Wisconsin, Michigan, Pennsylvania, Vermont and Maine', 'None as a rule; works alone, now and then with another Wishpoosh, a greater demon or an evil spirit', 'All mortals, Native Americans above all as its age-old foes', 'NPC monster, a Lesser Demon; no O.C.C. No equipment or valuables.', 'A scarce, giant demonic beaver of Nez Perce legend that delights in sinking boats, drowning swimmers, felling trees and damming rivers to flood or parch whole settlements. Arrogant and easily tricked, and vicious when it finds out.', 'Rifts World Book 20: Canada p.178-180'),
('tornaq-the-spirit-bear', 'Tornaq, the Spirit Bear', 'spirit', 'rifts', 0, NULL, '{}', NULL, NULL, NULL, '1D4x100+150', NULL, 'Attributes and abilities are printed only as those of a normal bear, typically a Polar Bear. M.D.C. is one point per point of P.P.E. its Angakoq has, plus 100; it regenerates 6D6 M.D.C. per hour. P.P.E. reserve 1D4x100+150, usable only by its Shaman, who can draw up to half as extra P.P.E.; each amulet or talisman made uses some of it up for good.', NULL, NULL, '{}', NULL, NULL, 'A Mega-Damage spirit guardian in bear shape. It finds food, tracks game and defends its Shaman, and fights to the death on command or in his defense but never for itself. The Shaman can will it away, back to the Spirit Realm, only when its life is truly at risk (typically at 20-25% of its M.D.C.); it comes back once he is safe. If it dies it is gone for good, along with its spells and P.P.E.', 'Held for the Shaman to cast, never the bear, each at most twice per 24 hours: Energy Disruption, Superhuman Strength, Swim as a Fish (superior), Impervious to Cold, Eyes of the Bear (as Eyes of the Wolf), Armor of Ithan, Turn Dead, Commune with Spirits, Exorcism, Constrain Being, Banishment, Control/Enslave Entity, Blind, Mute, Minor Curse, Remove Curse, Negate Magic, Dispel Magic Barrier, Stone to Flesh, Restoration, Anti-Magic Cloud, Amulet, Talisman, Summon and Control Animals, Summon Fog, Calm Storms, Aura of Power, Mystic Fulcrum, Fist of Fury, Frostblade, Tame Beast, Restore Life', NULL, NULL, NULL, NULL, NULL, 'Its Angakoq (Inuit Shaman) partner', NULL, 'Not a player character; the companion of the Angakoq O.C.C., joining a new Shaman within 72 hours. Said to be a child of the bear god Tornarssuk.', 'A bear-shaped spirit guardian, most often a polar bear, sent to accompany an Inuit Shaman for life. It is the store of power and spells the Shaman draws on for healing, weather and dealing with Sedna.', 'Rifts World Book 20: Canada p.182-183');
